// Game copy check. The player's disc folder (PS3_GAME) is compared with the
// retail BCUS98114 v02.00 files the engine reads: GT.VOL and the MOVIE videos
// (disc_files.h, generated by scripts/disc_manifest.py; no game content).
// full() checks each file is present at its exact size, then its SHA-256.
// Each file's hash is kept in <storage>/disc-check.ini with its path, size
// and write time, so a file is read again only after it changes (or with
// refresh); later starts cost a directory listing.
// A truncated or damaged extraction otherwise passes setup (which reads only
// PARAM.SFO and GT.VOL's presence) and fails later as freezes or crashes.
// PT5_DISC_CHECK=0 turns every check off. PT5_DISC_MANIFEST=<file> replaces
// the built-in list with "<bytes> <sha256> <path>" lines (tests only).
#pragma once
#include "disc_files.h"

namespace disc_check {
struct Entry { std::wstring path; uint64_t bytes; std::wstring sha256, sample; };
enum class Problem { missing, size, content, unreadable };
struct Finding { std::wstring path; Problem problem; uint64_t expected = 0, actual = 0; };
struct Result {
    std::vector<Finding> problems;
    bool complete = true;      // every file was read now or has a stored result
    uint64_t read_bytes = 0;   // bytes hashed by this check
};
using Progress = std::function<void(const std::wstring& file, double fraction)>;

inline bool enabled() {
    wchar_t b[8]; const DWORD n = GetEnvironmentVariableW(L"PT5_DISC_CHECK", b, 8);
    return !(n && n < 8 && b[0] == L'0');
}

inline std::vector<Entry> reference() {
    std::vector<Entry> out;
    std::vector<wchar_t> b(32768);
    const DWORD n = GetEnvironmentVariableW(L"PT5_DISC_MANIFEST", b.data(), static_cast<DWORD>(b.size()));
    if (!n || n >= b.size()) {
        for (const auto& d : disc_files) out.push_back({d.path, d.bytes, d.sha256, d.sample});
        return out;
    }
    // "<bytes> <sha256> <sample sha256 or -> <path>" per line.
    std::ifstream f{fs::path(b.data())};
    std::string line;
    auto wide = [](const std::string& s) { return std::wstring(s.begin(), s.end()); };
    while (std::getline(f, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const auto a = line.find(' '), c = a == std::string::npos ? a : line.find(' ', a + 1),
                   d = c == std::string::npos ? c : line.find(' ', c + 1);
        if (d == std::string::npos) continue;
        const std::string sample = line.substr(c + 1, d - c - 1);
        out.push_back({wide(line.substr(d + 1)), std::stoull(line.substr(0, a)), wide(line.substr(a + 1, c - a - 1)),
                       sample == "-" ? std::wstring{} : wide(sample)});
    }
    return out;
}

inline std::wstring native(const std::wstring& path) {
    std::wstring s = path;
    std::replace(s.begin(), s.end(), L'/', L'\\');
    return s;
}

// Empty when cancelled or unreadable (*unreadable set for the latter).
inline std::wstring sha256(const fs::path& p, const std::atomic<bool>& cancel,
                           const std::function<void(uint64_t)>& advance, bool* unreadable) {
    *unreadable = false;
    HANDLE h = CreateFileW(p.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                           nullptr, OPEN_EXISTING, FILE_FLAG_SEQUENTIAL_SCAN, nullptr);
    if (h == INVALID_HANDLE_VALUE) { *unreadable = true; return {}; }
    BCRYPT_ALG_HANDLE alg = nullptr; BCRYPT_HASH_HANDLE ctx = nullptr;
    DWORD object = 0, got = 0;
    NTSTATUS rc = BCryptOpenAlgorithmProvider(&alg, BCRYPT_SHA256_ALGORITHM, nullptr, 0);
    if (rc >= 0) rc = BCryptGetProperty(alg, BCRYPT_OBJECT_LENGTH, (PUCHAR)&object, sizeof object, &got, 0);
    std::vector<unsigned char> state(object), block(4u << 20);
    if (rc >= 0) rc = BCryptCreateHash(alg, &ctx, state.data(), object, nullptr, 0, 0);
    bool ok = rc >= 0;
    while (ok) {
        if (cancel) { ok = false; break; }
        DWORD n = 0;
        if (!ReadFile(h, block.data(), static_cast<DWORD>(block.size()), &n, nullptr)) { ok = false; *unreadable = true; break; }
        if (!n) break;
        if (BCryptHashData(ctx, block.data(), n, 0) < 0) { ok = false; *unreadable = true; break; }
        advance(n);
    }
    std::array<unsigned char, 32> digest{};
    if (ok && BCryptFinishHash(ctx, digest.data(), static_cast<ULONG>(digest.size()), 0) < 0) { ok = false; *unreadable = true; }
    if (ctx) BCryptDestroyHash(ctx);
    if (alg) BCryptCloseAlgorithmProvider(alg, 0);
    CloseHandle(h);
    if (!ok) return {};
    std::wstring out;
    for (auto byte : digest) { out += L"0123456789abcdef"[byte >> 4]; out += L"0123456789abcdef"[byte & 15]; }
    return out;
}

// The stored SHA-256 of a file, when it is the same file (path, size, time).
inline std::wstring identity(const fs::path& p) {
    std::error_code ec;
    const auto size = fs::file_size(p, ec);
    const auto time = ec ? 0 : fs::last_write_time(p, ec).time_since_epoch().count();
    if (ec) return {};
    return fs::absolute(p).lexically_normal().wstring() + L"|" + std::to_wstring(size) + L"|" + std::to_wstring(time) + L"|";
}
inline std::wstring stored(const fs::path& cache, const Entry& e, const std::wstring& id) {
    std::vector<wchar_t> b(4096);
    GetPrivateProfileStringW(L"disc", e.path.c_str(), L"", b.data(), static_cast<DWORD>(b.size()), cache.c_str());
    const std::wstring v = b.data();
    return !id.empty() && v.size() > id.size() && v.compare(0, id.size(), id) == 0 ? v.substr(id.size()) : std::wstring{};
}

// Bytes full() would read: present, right-sized files without a stored result.
inline uint64_t pending(const fs::path& game, const fs::path& cache, bool refresh = false) {
    uint64_t total = 0;
    for (const auto& e : reference()) {
        const auto p = game / e.path;
        std::error_code ec;
        if (fs::file_size(p, ec) != e.bytes || ec) continue;
        if (refresh || stored(cache, e, identity(p)).empty()) total += e.bytes;
    }
    return total;
}

// SHA-256 of 8 x 64 KiB spread evenly over the file (the whole file when it
// is smaller): scripts/disc_manifest.py's sample_sha256. Empty if unreadable.
inline std::wstring sample_sha256(const fs::path& p, uint64_t size) {
    constexpr uint64_t samples = 8, chunk = 65536;
    HANDLE h = CreateFileW(p.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                           nullptr, OPEN_EXISTING, 0, nullptr);
    if (h == INVALID_HANDLE_VALUE) return {};
    BCRYPT_ALG_HANDLE alg = nullptr; BCRYPT_HASH_HANDLE ctx = nullptr;
    DWORD object = 0, got = 0;
    NTSTATUS rc = BCryptOpenAlgorithmProvider(&alg, BCRYPT_SHA256_ALGORITHM, nullptr, 0);
    if (rc >= 0) rc = BCryptGetProperty(alg, BCRYPT_OBJECT_LENGTH, (PUCHAR)&object, sizeof object, &got, 0);
    std::vector<unsigned char> state(object), block(static_cast<size_t>(std::min(size, samples * chunk)));
    if (rc >= 0) rc = BCryptCreateHash(alg, &ctx, state.data(), object, nullptr, 0, 0);
    bool ok = rc >= 0;
    const uint64_t n = size <= samples * chunk ? 1 : samples, length = size <= samples * chunk ? size : chunk;
    for (uint64_t i = 0; ok && i < n; ++i) {
        LARGE_INTEGER at; at.QuadPart = static_cast<LONGLONG>(n == 1 ? 0 : i * (size - chunk) / (samples - 1));
        DWORD read = 0;
        ok = SetFilePointerEx(h, at, nullptr, FILE_BEGIN) && ReadFile(h, block.data(), static_cast<DWORD>(length), &read, nullptr) &&
             read == length && BCryptHashData(ctx, block.data(), read, 0) >= 0;
    }
    std::array<unsigned char, 32> digest{};
    if (ok) ok = BCryptFinishHash(ctx, digest.data(), static_cast<ULONG>(digest.size()), 0) >= 0;
    if (ctx) BCryptDestroyHash(ctx);
    if (alg) BCryptCloseAlgorithmProvider(alg, 0);
    CloseHandle(h);
    if (!ok) return {};
    std::wstring out;
    for (auto byte : digest) { out += L"0123456789abcdef"[byte >> 4]; out += L"0123456789abcdef"[byte & 15]; }
    return out;
}

// The fast pass, run before full(): missing files, sizes, stored results, and
// a sample of each file without one (about 512 KiB per file). It finds a copy
// extracted from an encrypted disc image without reading 18 GiB.
inline Result screen(const fs::path& game, const fs::path& cache) {
    Result r;
    for (const auto& e : reference()) {
        const auto p = game / e.path;
        std::error_code ec;
        const auto size = fs::file_size(p, ec);
        if (ec) { r.problems.push_back({e.path, Problem::missing, e.bytes}); continue; }
        if (size != e.bytes) { r.problems.push_back({e.path, Problem::size, e.bytes, size}); continue; }
        const auto hash = stored(cache, e, identity(p));
        if (!hash.empty()) {
            if (_wcsicmp(hash.c_str(), e.sha256.c_str()) != 0) r.problems.push_back({e.path, Problem::content, e.bytes});
            continue;
        }
        r.complete = false;   // full() still has to read it
        if (e.sample.empty()) continue;
        const auto sample = sample_sha256(p, size);
        if (sample.empty()) r.problems.push_back({e.path, Problem::unreadable, e.bytes});
        else if (_wcsicmp(sample.c_str(), e.sample.c_str()) != 0) r.problems.push_back({e.path, Problem::content, e.bytes});
    }
    return r;
}

inline Result full(const fs::path& game, const fs::path& cache, bool refresh,
                   const std::atomic<bool>& cancel, const Progress& progress) {
    Result r;
    // A UTF-16 file keeps any path; WritePrivateProfileStringW would create an ANSI one.
    if (!fs::exists(cache)) { std::ofstream f(cache, std::ios::binary); f.write("\xff\xfe", 2); }
    const uint64_t total = std::max<uint64_t>(pending(game, cache, refresh), 1);
    for (const auto& e : reference()) {
        const auto p = game / e.path;
        std::error_code ec;
        const auto size = fs::file_size(p, ec);
        if (ec) { r.problems.push_back({e.path, Problem::missing, e.bytes}); continue; }
        if (size != e.bytes) { r.problems.push_back({e.path, Problem::size, e.bytes, size}); continue; }
        const auto id = identity(p);
        std::wstring hash = refresh ? std::wstring{} : stored(cache, e, id);
        if (hash.empty()) {
            if (cancel) { r.complete = false; continue; }
            bool unreadable = false;
            progress(native(e.path), static_cast<double>(r.read_bytes) / total);
            hash = sha256(p, cancel, [&](uint64_t n) {
                r.read_bytes += n;
                progress(native(e.path), static_cast<double>(r.read_bytes) / total);
            }, &unreadable);
            if (unreadable) { r.problems.push_back({e.path, Problem::unreadable, e.bytes}); continue; }
            if (hash.empty()) { r.complete = false; continue; }
            WritePrivateProfileStringW(L"disc", e.path.c_str(), (id + hash).c_str(), cache.c_str());
        }
        if (_wcsicmp(hash.c_str(), e.sha256.c_str()) != 0) r.problems.push_back({e.path, Problem::content, e.bytes});
    }
    WritePrivateProfileStringW(nullptr, nullptr, nullptr, cache.c_str());   // flush
    return r;
}

// One line per problem, at most max_lines (then a count of the rest).
inline std::wstring describe(const Result& r, size_t max_lines = 8) {
    std::wstring s;
    for (size_t i = 0; i < r.problems.size(); ++i) {
        if (i == max_lines) { s += L"• and " + std::to_wstring(r.problems.size() - i) + L" more files.\n"; break; }
        const auto& f = r.problems[i];
        s += L"• " + native(f.path);
        switch (f.problem) {
        case Problem::missing: s += L" is missing."; break;
        case Problem::size: s += L" is the wrong size (" + std::to_wstring(f.actual) + L" bytes; the retail disc has " + std::to_wstring(f.expected) + L")."; break;
        case Problem::content: s += L" is damaged: its contents differ from the retail disc."; break;
        case Problem::unreadable: s += L" could not be read (a disk or drive error)."; break;
        }
        s += L"\n";
    }
    return s;
}

// Files of the right size with different bytes: what files extracted from an
// encrypted PS3 disc image look like (issues #15 and #35: GT.VOL at its exact
// size, a different hash, and RPCS3 refusing the folder too).
inline bool same_size_different_bytes(const Result& r) {
    for (const auto& f : r.problems) if (f.problem == Problem::content) return true;
    return false;
}

// For crash reports and the debug export: "verified", "not fully checked"
// or "problems: <file> <kind>, ...".
inline std::wstring status(const Result& r) {
    if (r.problems.empty()) return r.complete ? L"verified" : L"not fully checked";
    std::wstring s = L"problems:";
    for (size_t i = 0; i < r.problems.size() && i < 6; ++i) {
        const auto& f = r.problems[i];
        s += (i ? L", " : L" ") + f.path + (f.problem == Problem::missing ? L" missing" : f.problem == Problem::size ? L" wrong size"
              : f.problem == Problem::content ? L" damaged" : L" unreadable");
    }
    if (r.problems.size() > 6) s += L", +" + std::to_wstring(r.problems.size() - 6) + L" more";
    return s;
}
}  // namespace disc_check
